type Either<E, A> = { tag: "left"; error: E } | { tag: "right"; value: A };
const left  = <E, A = never>(error: E): Either<E, A> => ({ tag: "left", error });
const right = <E = never, A = never>(value: A): Either<E, A> => ({ tag: "right", value });

function describe(r: Either<string, number>): string {
  switch (r.tag) {
    case "right": return `ok: ${r.value}`;      // r narrowed to the right branch
    case "left":  return `failed: ${r.error}`;
    default: {
      const impossible: never = r;               // a new tag breaks the build here
      throw new Error(`unhandled: ${JSON.stringify(impossible)}`);
    }
  }
}

