import * as E from 'fp-ts/Either';
import { pipe } from 'fp-ts/function';

const parsePort = (text: string): E.Either<string, number> => {
  const port = Number.parseInt(text, 10);
  return Number.isNaN(port) ? E.left(`not a number: ${text}`) : E.right(port);
};

const label = pipe(
